mapper.select:
select  from account_sync_commands
where user_id = #{userId} and app_code = #{appCode} and sync_version = #{version}
order by created_at desc, id desc limit 1

mapper.update:
update account_sync_commands set status = 'superseded', payload_json = null,
    lease_token = null, lease_expires_at = null, next_retry_at = null, updated_at = #{now}
where user_id = #{userId} and app_code = #{appCode} and sync_version < #{version}
  and status not in ('succeeded', 'superseded', 'expired')

update account_application_user_states set applied_status = #{state.appliedStatus},
    applied_version = #{state.appliedVersion}, last_synced_at = #{state.lastSyncedAt},
    updated_by = #{state.updatedBy}, updated_at = #{state.updatedAt}
where user_id = #{state.userId} and app_code = #{state.appCode}
